import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    result = []

    for line in lines:
        if not line:
            result.append('-1')
            continue

        n = int(line)
        digits = []

        for digit in str(n):
            d = int(digit)
            if d % 2 == 1:
                digits.append(digit)

        if not digits:
            result.append('-1')
        else:
            result.append(' '.join(digits))

    print('\n'.join(result))

if __name__ == "__main__":
    main()
